window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-42201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · υ 1195⟧</h1><div class=\"entry-meta\"><span>DGP · ordem 1195 na letra υ · nº geral 42201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑψόω-ῶ 1 elevar; erguer (a voz) 2 exaltar; glorificar 3 erguer; edificar (túmulo) 4 Astron. (astro) levantar; sair. 〈ὕψος〉</p></section></article>\n<article id=\"entry-dgp-42202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕψωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1196 na letra υ · nº geral 42202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 posição elevada: ὕ. μέγιστον plut. ponto culminante 2 exaltação; glória 3 Astron. elevação; o erguer-se; o levantar (dos astros). 〈ὑψόω〉</p></section></article>\n<article id=\"entry-dgp-42203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑψώροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1197 na letra υ · nº geral 42203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑψόροφος.</p></section></article>\n<article id=\"entry-dgp-42204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕω</h1><div class=\"entry-meta\"><span>DGP · ordem 1198 na letra υ · nº geral 42204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὕσω, aor. ὗσα, perf. desus.; pas. aor. ὕσθην) 1 intr. fazer chover: Ζεὺς ὗε hom. Zeus fazia chover, ὁ θεὸς ὕει her. o deus faz chover 2 impes. chover: ὕοντος πολλῷ xen. como chovia muito, πολὺ ὕσαντος teofr. depois que chove muito 3 fazer cair como chuva; fazer chover algo: ἐγὼ ὕω ἄρτους ἐκ τοῦ οὐρανοῦ sept. faço chover pães do céu 4 molhar de chuva ♦ pas. 5 (chuva) cair: ὕδωρ ὑόμενον plut. chuva que cai 6 estar molhado de chuva: ὕεσθαι ὀλίγῳ her. estar um pouco molhado de chuva 7 ser respingado de, dat.: ὕσθη δὲ καὶ σταγόσιν αἵματος ἡ πόλις plut. a cidade ficou respingada de gotas de sangue.</p></section></article>\n<article id=\"entry-dgp-42205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1199 na letra υ · nº geral 42205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de porco; suíno. 〈ὗς, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-42206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 1200 na letra υ · nº geral 42206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. de ὗς.</p></section></article>\n<article id=\"entry-dgp-42207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φ, φ (φῖ) (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra φ · nº geral 42207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. 1 fi, 21ª letra do alfabeto ♦ num. 2 φʹ = 500 ou 500º 3 ͵φ = 500.000 ou 500.000º.</p></section></article>\n<article id=\"entry-dgp-42208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαάνθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra φ · nº geral 42208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl., φαάνθην 1a sing., aor. pas. ép. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαάντατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra φ · nº geral 42209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito brilhante; o mais brilhante.</p></section></article>\n<article id=\"entry-dgp-42210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαβίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra φ · nº geral 42210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de φάψ.</p></section></article>\n<article id=\"entry-dgp-42211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγέδαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra φ · nº geral 42211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. cancro; úlcera 2 Medic. fome canina.</p></section></article>\n<article id=\"entry-dgp-42212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγεδαινικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra φ · nº geral 42212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que corrói; que carcome (doença). 〈φαγέδαινα〉</p></section></article>\n<article id=\"entry-dgp-42213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra φ · nº geral 42213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ἐσθίω.</p></section></article>\n<article id=\"entry-dgp-42214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra φ · nº geral 42214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φάγομαι.</p></section></article>\n<article id=\"entry-dgp-42215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάγῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra φ · nº geral 42215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. subj. aor.2 poét. de ἐσθίω.</p></section></article>\n<article id=\"entry-dgp-42216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάγιλος, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra φ · nº geral 42216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cordeiro ou cabrito pronto para o abate ou que começa a pastar. 〈φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-42217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάγομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra φ · nº geral 42217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e fut.) comer.</p></section></article>\n<article id=\"entry-dgp-42218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάγος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra φ · nº geral 42218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) bíbl. glutão; comilão. 〈φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-42219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαγός</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra φ · nº geral 42219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = φηγός.</p></section></article>\n<article id=\"entry-dgp-42220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάε</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra φ · nº geral 42220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φάω.</p></section></article>\n<article id=\"entry-dgp-42221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαέθουσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra φ · nº geral 42221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Faetusa, lit. brilhante, filha de Hélios. 〈φαέθων〉</p></section></article>\n<article id=\"entry-dgp-42222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαέθων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra φ · nº geral 42222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 brilhante, epít. do sol ♦ ὁ φαέ­θων 2 o sol; o dia ♦ Φαέθων 3 Faetonte, filho de Hélios 4 o planeta Júpiter. 〈φάος〉</p></section></article>\n<article id=\"entry-dgp-42223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαεινός, ή,</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra φ · nº geral 42223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 brilhante; luzente; cintiliante (cinta) 2 esplêndido (virtude, sacrifício) 3 claro (voz). 〈φάος〉</p></section></article>\n<article id=\"entry-dgp-42224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 18 na letra φ · nº geral 42224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 intr. (sol, aurora, archote) brilhar; resplandecer 2 trazer à luz; fazer aparecer. 〈φάος〉</p></section></article>\n<article id=\"entry-dgp-42225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαεσίμβροτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 19 na letra φ · nº geral 42225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que brilha para os mortais; luminoso (sol, aurora). 〈φάος, βροτός〉</p></section></article>\n<article id=\"entry-dgp-42226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 20 na letra φ · nº geral 42226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. poét. de φάος.</p></section></article>\n<article id=\"entry-dgp-42227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάθι</h1><div class=\"entry-meta\"><span>DGP · ordem 21 na letra φ · nº geral 42227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φαθί 2ª sing. imper. pres. de φημί.</p></section></article>\n<article id=\"entry-dgp-42228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαίακες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 22 na letra φ · nº geral 42228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Feácios, povo mítico.</p></section></article>\n<article id=\"entry-dgp-42229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδιμόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 23 na letra φ · nº geral 42229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φαίδιμος.</p></section></article>\n<article id=\"entry-dgp-42230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαίδιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra φ · nº geral 42230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brilhante de força; vigoroso; esplêndido (corpo, cabeleira) 2 magnífico; glorioso; ilustre (herói). 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαίδρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra φ · nº geral 42231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Fedra, filha de Minos, esposa de Teseu.</p></section></article>\n<article id=\"entry-dgp-42232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρόνους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra φ · nº geral 42232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de espírito alegre; ledo. 〈φαιδρός, νοῦς〉</p></section></article>\n<article id=\"entry-dgp-42233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 27 na letra φ · nº geral 42233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brilhante; luminoso 2 claro; sereno; puro 3 alegre; feliz; radiante ♦ τὸ φαιδρόν 4 serenidade ou alegria.</p></section></article>\n<article id=\"entry-dgp-42234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 28 na letra φ · nº geral 42234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 luminosidade 2 brilho suave (do olhar) 3 alegria; júbilo. 〈φαιδρός〉</p></section></article>\n<article id=\"entry-dgp-42235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 29 na letra φ · nº geral 42235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar-se alegre, radiante. 〈φαιδρός〉</p></section></article>\n<article id=\"entry-dgp-42236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρύντρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 30 na letra φ · nº geral 42236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lavadeira. 〈φαιδρύνω〉</p></section></article>\n<article id=\"entry-dgp-42237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 31 na letra φ · nº geral 42237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐφαίδρυνα) 1 fazer brilhar 2 fazer brilhar de alegria; tornar feliz 3 limpar; lavar 4 arrumar; embelezar; adornar 5 lamber ♦ pas. 6 tornar-se feliz; mostrar-se alegre. 〈φαιδρός〉</p></section></article>\n<article id=\"entry-dgp-42238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιδρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 32 na letra φ · nº geral 42238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo radiante; alegremente; serenamente.</p></section></article>\n<article id=\"entry-dgp-42239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαίδων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 33 na letra φ · nº geral 42239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Fédon, n. de h.</p></section></article>\n<article id=\"entry-dgp-42240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαιήκες</h1><div class=\"entry-meta\"><span>DGP · ordem 34 na letra φ · nº geral 42240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Φαιάκες.</p></section></article>\n<article id=\"entry-dgp-42241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαικάσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 35 na letra φ · nº geral 42241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fecasio, calçado branco usado pelos ginasiarcos atenienses e sacerdotes egípcios.</p></section></article>\n<article id=\"entry-dgp-42242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιλόνης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 36 na letra φ · nº geral 42242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = φαινόλης.</p></section></article>\n<article id=\"entry-dgp-42243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαινέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 37 na letra φ · nº geral 42243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαινέσκετο</h1><div class=\"entry-meta\"><span>DGP · ordem 38 na letra φ · nº geral 42244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. impf. iter. pas. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαινόλης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 39 na letra φ · nº geral 42245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capa com capuz, para viagem.</p></section></article>\n<article id=\"entry-dgp-42246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαινομένῃφιν</h1><div class=\"entry-meta\"><span>DGP · ordem 40 na letra φ · nº geral 42246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. méd. fem. dat. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 41 na letra φ · nº geral 42247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φανῶ, aor. ἔφηνα, perf.1 πέφαγκα, perf.2 intr. πέφηνα; méd. fut. φανοῦμαι e φανήσομαι, aor.1 ἐφηνάμην e ἐφάνθην; aor. méd. φήνασθαι, aor.2 ἐφάνην, perf.2 πέφηνα; pas. fut. φανήσομαι, aor.1 ἐφάνθην, aor.2 ἐφάνην, perf. πέφασμαι) ativa 1 fazer brilhar 2 encher de luz ou trazer luz; alumiar 3 fazer aparecer; tornar visível ou audível; manifestar algo, ac., a alguém, dat. 4 fazer conhecer; indicar; fazer conhecer pela palavra, revelar algo, ac., a alguém, dat. 5 indicar; atribuir algo ou alguém, a alguém, dat. 6 Jur. denunciar, uma pessoa, ac., a outra, dat. 7 explicar; esclarecer; revelar, ac. 8 Mil., decretar a mobilização (de tropa) ativa e média 9 intr. brilhar; reluzir; resplender 9 brilhar; luzir 10 intr. (pessoa) mostrar-se; aparecer; perf. fazer-se presente média 11 mostrar algo de si ou que lhe pertence 12 surgir 13 vir ao mundo; nascer 14 tornar-se visível; aparecer como; mostrar-se como; φαινόμενος, η, ον Fil. que se pode perceber; que se pode ver com clareza; nítido; evidente 15 tornar-se 16 ser manifesto, evidente 17 ser manifesto, com part. predic. 18 parecer (op. a ser), inf.; φαινόμενος, η, ον Fil. aparente 19 impes., parecer bom ou oportuno, or. inf. passiva 20 jur. ser denunciado 1 μόλις ἔφην᾽ ἄφαντον φῶς sóf. com dificuldade fiz brilhar uma luz pouco visível, φαίνετε ὑμεῖς τούτῳ λαμπάδας ἱεράς ar. acendei para ele [Ésquilo] tochas sagradas 2 φαίνοντες νύκτας κατὰ δώματα δαιτυμόνεσσι hom. [estátuas portadoras de tochas] alumiando as noites para os convivas no palácio, οἱ λύχνοι φαίνουσιν ἧττον teofr. os candeeiros iluminam menos, ἵνα ὅτι μάλιστα εἰς ἅπαντα φαίνοι οὐρανόν plat. para que trouxesse luz o mais possível a todo o céu 3 τὸν αὐχένα δὲ καὶ κεφαλὴν φαίνει her. mostra o pescoço e a cabeça, ἐναίσιμα σήματα φαίνων hom. tornando visíveis sinais auspiciosos, ἡμῖν μὲν τόδ᾽ ἔφηνε τέρας μέγα hom. [Zeus] mostrou-nos esse grande sinal, φαῖνε δ᾽ ἀοιδήν hom. [o aedo] fazia ressoar o canto, πᾶσαν φαῖνε βίην hes. toda violência ele mostrava 4 θεοῖσιν εὐξαίμην, εἴ τίς μοι ὁδὸν φήνειε νέεσθαι hom. implorei aos deuses, a ver se alguém me indicaria um caminho para regressar, εἰς τὸ φῶς φανεῖ κακά sóf. trará à luz as infâmias, εἶπεν ὁ μάντις ὅτι ἐπιβουλήν τινα τῶν δεινοτάτων φαίνοιεν οἱ θεοί xen. o adivinho disse que os deuses anunciavam uma conjuração das mais terríveis, ἡμᾶς σὺ δειλοὺς φανεῖς sóf. tu nos darás a conhecer como covardes 5 εἰς ὅ κέ τοι φήνωσι θεοὶ κυδρὴν παράκοιτιν hom. até que os deuses te indiquem uma ilustre esposa, Ἑλένῃ δὲ θεοὶ γόνον οὐκέτ᾽ ἔφαινον hom. a Helena os deuses não mais indicavam uma prole 6 φανῶ σε τοῖς πρυτάνεσιν ar. vou denunciar-te aos prítanes 7 ἔφαινε τὸν ἐόντα λόγον her. [o boieiro] revelou a história verdadeira 8 εἰς δὲ τὸ Ἄργος φρουρὰν φαίνουσιν xen. decretam a mobilização de uma guarnição contra Argos, πάλιν φρουρὰν ἔφαινεν ἐπὶ τοὺς Ἀκαρνᾶνας xen. de novo ia mobilizando uma guarnição contra os acarnânios 9 οὐ φανεῖν ἔφασκεν ὑμῖν εἰ στρατηγήσει Κλέων ar. [o sol] dizia que não brilharia para vós se Cleão fosse estratego, ὁ φαίνων artt. o astro brilhante, i.e., Saturno, τὸ φῶς ἐν τῇ σκοτίᾳ φαίνει n.t. a luz resplende nas trevas, δεινὼ δέ οἱ ὄσσε φάανθεν hom. seus olhos brilharam terríveis, διὰ τοῦ ὀρόφου ἐφαίνετο πῦρ xen. o fogo brilhava através do teto, ὅτ᾽ ἄν ἐκ πόντοιο σέλας ναύτῃσι φανήῃ πυρός hom. quando o brilho do fogo, no seio do mar, brilha para os marinheiros, ἄστρα φαεινὴν ἀμφὶ σελήνην φαίνεται hom. estrelas reluzem ao redor da lua reluzente 10 τίνες δόμων ὕπερ φαίνουσι; eur. quem são esses que aparecem acima da casa? τέκνον, πέφηνας; sóf. filha, estás aqui? Τρώεσσι φάνηθι hom. mostra-te aos troianos, πόθεν φαίνει; plat. de onde surges?, i.e., de onde vens? 11 τὰ τόξα τοῖσ᾽ Ἀργείοισι φήνασθαι θέλει sóf. quer mostrar as armas aos argivos 12 ἐφάνη λῖς εἰς ὁδόν hom. um leão surgiu no caminho, ἔνθ᾽ ἐφάνη μέγα σῆμα hom. surgiu então um terrível sinal, ἦμος φάνη ῥοδοδάκτυλος ἠώς hom. quando apareceu a aurora de dedos róseos, ἅμ᾽ ἠοῖ φαινομένῃφιν hom. ao surgir da aurora, ao amanhecer, ὁδὸν φανῆναι eur. aparecer no caminho, τὰ φαινόμενα pol. as constelações visíveis ou os fenômenos celestes, τὸ φανθέν sóf. o acontecido, οὐδαμοῦ φαίνεσθαι xen. não aparecer em lugar nenhum, não ter importância 13 φανεὶς δύστηνος, ὡς ἐγὼ φάνην sóf. nascido infeliz, como eu nasci 14 γαία μέλαινα φάνεσκε hom. terra negra aparecia [no fundo da água], ἔνθεν γὰρ ἐφαίνετο πᾶσα μὲν Ἴδη, φαίνετο δὲ Πριάμοιο πόλις hom. de lá era visível todo o Ida, era visível a cidade de Príamo, φάνεν δὲ οἱ εὐρέες ὦμοι hom. seus largos ombros apareceram, φανεῖσα Παρνασοῦ φάμα sóf. voz que ressoa do Parnasso, φάνητε τῶν λοχαγῶν ἄριστοι xen. mostrai-vos os melhores dos comandantes, ἀρχαῖα φαίνομαι λέγειν ésql. parece que digo velharias, εἰ βούλοιτο στρατηγὸς ἀγαθὸς μὴ ὢν φαίνεσθαι xen. se alguém quisesse mostrar-se bom general, embora não o fosse, εἴτε τὰ δοκοῦντα πάντα ἐστὶν ἀληθῆ καὶ τὰ φαινόμενα artt. se são verdadeiras todas as opiniões e as coisas percebidas sensorialmente 15 ἐκ βασιλέως ἰδιώτην φανῆναι xen. de rei [que era] tornar-se um homem comum 16 ἐστὶν ἀληθῆ καὶ φαίνεται dem. isso é verdadeiro e manifesto, ἀδύνατος ἂν φαινοίμην xen. eu me mostraria incapaz [de fazer isso], ἐὰν φαίνωμαι ἀδικεῖν xen. se ficar claro que agi mal 17 φαίνεται γὰρ ἡ νῦν Ἑλλὰς καλουμένη οὐ πάλαι βεβαίως οἰκουμένη tuc. evidentemente, a região hoje denominada Hélada não tinha outrora população estável, τῶν ἡλίκων διαφέρων ἐφαίνετο xen. era, evidentemente, superior aos de sua idade, εὖ ποιεῦντες φαίνεσθε her. mostrai-vos que estais fazendo boas ações, Πέρσαι φανέονται λέγοντες οὐδέν her. estará claro que os persas estão dizendo tolices 18 τί ὑμῖν φαίνεται; n.t. que vos parece? οὕτως ἔμοιγε καὶ αὐτῷ φαίνεται σοῦ λέγοντος plat. é assim que também me parece, quando tu falas, οὗ ἀρίστη φαίνετο βουλή hom. cuja opinião parecia [ser] melhor, ὥς γ᾽ ἐμοὶ φαίνεται plat. como me parece, δοκοῖμεν ἂν τῶν πατέρων χείρους φαίνεσθαι tuc. pareceríamos inferiores aos nossos pais, εἰ δὴ κακός τε φαίνομαι δοκῶ τέ σοι eur. se te pareço uma pessoa malvada e é isso que pensas, εὖ σὺ λέγειν φαίνει ar. tu pareces ter razão, τὸ φαινόμενον εἰπεῖν plut. dizer o que nos parece, φαινόμενα, οὐ μέντοι ὄντα γέ που τῇ ἀληθείᾳ plat. [criarás] coisas aparentes que, na realidade, não existem 19 ὁπότε αὐτῷ φανείη στρατιὰν ἐξάγειν d.c. quando lhe parecesse oportuno retirar o exército 20 τὰ ἡμίση τῶν φανθέντων λαβεῖν dem. tomar a metade das coisas postas sob denúncia.</p></section></article>\n<article id=\"entry-dgp-42248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 42 na letra φ · nº geral 42248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escuro; sombrio 2 áspero; surdo (som). 〈φάος〉</p></section></article>\n<article id=\"entry-dgp-42249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαιοχίτων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra φ · nº geral 42249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que traja uma roupa escura. 〈φαιός, χιτών〉</p></section></article>\n<article id=\"entry-dgp-42250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φακέα</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra φ · nº geral 42250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φακῆ.</p></section></article>\n<article id=\"entry-dgp-42251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάκελος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra φ · nº geral 42251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feixe (de lenha ou de ramos).</p></section></article>\n<article id=\"entry-dgp-42252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φακῆ, ῆς</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra φ · nº geral 42252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de φακέα, ας (ἡ) prato ou purê de lentilhas. 〈φακός〉</p></section></article>\n<article id=\"entry-dgp-42253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φακοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra φ · nº geral 42253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em forma de lentilha; lenticular. 〈φακός, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-42254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φακός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra φ · nº geral 42254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lentilha, planta e grão 2 sardas 3 qualquer vasilhame em forma de lentilha.</p></section></article>\n<article id=\"entry-dgp-42255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλαγγηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra φ · nº geral 42255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em ordem de batalha; em falange. 〈φάλαγξ, -δον〉</p></section></article>\n<article id=\"entry-dgp-42256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλάγγιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra φ · nº geral 42256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tarântula, aranha venenosa 2 antérico, planta usada contra picada de aranha. 〈φάλαγξ〉</p></section></article>\n<article id=\"entry-dgp-42257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλαγγομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra φ · nº geral 42257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lutar em combate de infantaria. 〈φά­λαγξ, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-42258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάλαγξ, αγγος</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra φ · nº geral 42258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ἡ) 1 pedaço de madeira grosso e redondo; bastão; cilindro (para deslocar fardos) 2 Mil. fileira ou ordem de batalha; tropa alinhada ou frota alinhada 3 Mil. linha de batalha; frente da tropa: ἄγειν ἐπὶ φάλαγγος xen. fazer avançar em linha de frente, ἐκ κέρατος εἰς φάλαγγα καταστῆσαι xen. formar uma tropa de colunas em linha, ἐπὶ φάλαγγος καθίστασθαι xen. formar-se em linha 4 Mil. linha de batalha da infantaria macedônia ou da legião romana 5 exército; centro de um exército 6 exército em marcha 7 exército acampado; acampamento 8 santola navalheira, espécie de aranha 9 braço da balança; travessão 10 Anat. falange (do dedo, do artelho).</p></section></article>\n<article id=\"entry-dgp-42259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάλαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra φ · nº geral 42259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 baleia 2 com. monstro voraz 3 falena; mariposa.</p></section></article>\n<article id=\"entry-dgp-42260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλακρός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra φ · nº geral 42260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calvo 2 polido; liso 3 monótono ♦ τὰ φαλακρά 4 rochedos nus. 〈φαλός〉</p></section></article>\n<article id=\"entry-dgp-42261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλακρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra φ · nº geral 42261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">calvície. 〈φαλακρός〉</p></section></article>\n<article id=\"entry-dgp-42262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλάκρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra φ · nº geral 42262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o tornar-se calvo. 〈φαλακρός〉</p></section></article>\n<article id=\"entry-dgp-42263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλαντίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra φ · nº geral 42263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">calvície. 〈φάλος〉</p></section></article>\n<article id=\"entry-dgp-42264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάλαρα, -ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra φ · nº geral 42264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φάλαρος.</p></section></article>\n<article id=\"entry-dgp-42265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαλαρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra φ · nº geral 42265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">galinha d’água. 〈φαλαρός〉</p></section></article>\n<article id=\"entry-dgp-42266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάλαρις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra φ · nº geral 42266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. ιν (ὁ) Faláris, tirano de Agrigento.</p></section></article>\n<article id=\"entry-dgp-42267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάλαρος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra φ · nº geral 42267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φαλαρός, ά, όν 1 manchado de branco ♦ τὰ φάλαρα 2 placas de metal brilhante que desciam do capacete sobre as faces e se fixavam sob o queixo com ajuda de correias também com placas 3 revestimento de um cavalo 4 ornamento para a cabeça. 〈φάλος〉</p></section></article>\n<article id=\"entry-dgp-42268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαληριάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra φ · nº geral 42268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. ép. pl. n. φαληρίωντα) ficar branco como espuma. 〈φαληρός〉</p></section></article>\n<article id=\"entry-dgp-42269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαληρίς</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra φ · nº geral 42269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φαλαρίς.</p></section></article>\n<article id=\"entry-dgp-42270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάληροι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra φ · nº geral 42270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Φάληρον.</p></section></article>\n<article id=\"entry-dgp-42271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαληροῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra φ · nº geral 42271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em Falero. 〈Φάληρον〉</p></section></article>\n<article id=\"entry-dgp-42272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάληρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra φ · nº geral 42272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Falero, porto de Atenas.</p></section></article>\n<article id=\"entry-dgp-42273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαληρόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra φ · nº geral 42273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção a Falero. 〈Φάληρον, δε〉</p></section></article>\n<article id=\"entry-dgp-42274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαληρός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra φ · nº geral 42274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φαλαρός.</p></section></article>\n<article id=\"entry-dgp-42275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φαλίνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 69 na letra φ · nº geral 42275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Falino, n. de h.</p></section></article>\n<article id=\"entry-dgp-42276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 70 na letra φ · nº geral 42276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extremidade do capacete; cimeira.</p></section></article>\n<article id=\"entry-dgp-42277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάμα</h1><div class=\"entry-meta\"><span>DGP · ordem 71 na letra φ · nº geral 42277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = φήμη.</p></section></article>\n<article id=\"entry-dgp-42278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 72 na letra φ · nº geral 42278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φημί.</p></section></article>\n<article id=\"entry-dgp-42279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 73 na letra φ · nº geral 42279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. méd. de φημί.</p></section></article>\n<article id=\"entry-dgp-42280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαμί</h1><div class=\"entry-meta\"><span>DGP · ordem 74 na letra φ · nº geral 42280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = φημί.</p></section></article>\n<article id=\"entry-dgp-42281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάν</h1><div class=\"entry-meta\"><span>DGP · ordem 75 na letra φ · nº geral 42281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. impf. poét. de φημί.</p></section></article>\n<article id=\"entry-dgp-42282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάνεν</h1><div class=\"entry-meta\"><span>DGP · ordem 76 na letra φ · nº geral 42282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. aor.2 pas. ép. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερόμισος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 77 na letra φ · nº geral 42283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que odeia abertamente. 〈φανερός, μισέω〉</p></section></article>\n<article id=\"entry-dgp-42284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 78 na letra φ · nº geral 42284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode ver ou que se mostra; visível; aparente: φανεροὶ θεοί her. deuses que se mostram aos homens, deuses visíveis, φανερὰ οὐσία dem. fortuna visível, bens móveis e imóveis, φανερὰ ἔχθρα tuc. inimizade declarada, φανερὸς ὄμμασιν eur. visível aos olhos, τὴν ψῆφον φανερὰν φέρειν ou τιθέναι plat. levar ou depositar voto aberto 2 claro; evidente; manifesto; com part. ou com or. conj. (ὅτι): ἐπισπεύδων φανερὸς ἦν her. punha-se abertamente a apressar [a expedição], φανεροὶ γιγνόμενοι ὅτι ποιοῦσιν xen. é evidente que fazem, ἐκ τοῦ φανεροῦ tuc. abertamente ou em um lugar descampado, ou da parte visível do espaço, i.e., ao alcance da vista, ἐν φανερῷ tuc. e ἐν τῷ φανερῷ xen. em público, à luz do dia, ἐς τὸ φανερόν aos olhos de todos, à luz do dia, ἀπὸ τοῦ φανεροῦ d.h. à vista de todos, ὑπ᾽ οὐδενὸς φανεροῦ plut. sem causa evidente, φανερὸς ἦν ἐπιθυμῶν εἰπεῖν plat. era evidente que queria falar, φανερόν ἐστιν ὅτι xen. é evidente que, εἰ φανερὸν γένοιτο ὅτι plat. se se tornasse evidente que; n. φανερὸν δὲ é evidente que, isso é evidente 3 o que está à vista: εἰς τὸ φανερὸν καταστῆσαι xen. pôr em evidência, em condição elevada 4 distinto; célebre; importante (pessoa, coisa). 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 79 na letra φ · nº geral 42285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἐφανερώθην) fazer conhecer; tornar notório ou célebre. 〈φανερός〉</p></section></article>\n<article id=\"entry-dgp-42286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανερῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 80 na letra φ · nº geral 42286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 visivelmente; abertamente 2 sob os olhos de todos; publicamente.</p></section></article>\n<article id=\"entry-dgp-42287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανέρωσις, έως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 81 na letra φ · nº geral 42287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o tornar visível; manifestação; desvelamento 2 revelação profética 3 ação de comunicar por sinais; sinalização. 〈φανερόω〉</p></section></article>\n<article id=\"entry-dgp-42288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανέσκε</h1><div class=\"entry-meta\"><span>DGP · ordem 82 na letra φ · nº geral 42288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. inter. at., φανήῃ 3ª sing. subj. aor.2 pas. ép., φάνηθι 2a sing. imper. aor.2 pas., φανήμεναι inf. aor.2 pas. ép., de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φάνης, ητος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 83 na letra φ · nº geral 42289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Fanes, n. de h.</p></section></article>\n<article id=\"entry-dgp-42290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανθείς, εῖσα, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 84 na letra φ · nº geral 42290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de φαίνω.</p></section></article>\n<article id=\"entry-dgp-42291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανός1, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 85 na letra φ · nº geral 42291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 claro; luminoso; brilhante 2 brilhante de limpeza (roupa); limpo 3 radiante; feliz 4 célebre; ilustre (pessoa) ♦ τὸ φανόν 5 claridade; luminosidade 6 pl. quartos luminosos. 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανός2, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 86 na letra φ · nº geral 42292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">archote; tocha; lanterna: ὑπὸ φανοῦ xen. à luz de archotes. 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 87 na letra φ · nº geral 42293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φαντάσω, aor. ἐφάντασα; pas. φαντασ­θήσομαι, aor. ἐφαντάσθην, perf. desus.) 1 tornar visível; mostrar 2 iludir; enganar (a percepção) ♦ méd. 3 (visão, cometa) mostrar-se; aparecer: ὄνειρον φαντά­ζεταί μοι her. aparece-me um sonho, φαντάζεσθαι ἄλλοτε ἐν ἄλλαις ἰδέαις plat. aparecer ora sob uma forma ora sob outra, δεξιὰ φαντάζεται τὰ ἀριστερά plat. o que está à esquerda parece estar à direita, τὸ φανταζόμενον n.t. o espetáculo 4 fazer ostentação; pavonear-se: [τὰ ὑπερέχον­τα ζῷα] ὁ θεὸς οὐδὲ ἐᾷ φαντάζεσθαι her. o deus não deixa que as criaturas de grande porte se pavoneiem 5 mostrar-se sob os traços de; assumir o semblante de, dat.: φαν­ταζόμενος δὲ γυναικὶ νεκροῦ ésql. [o nume vingador] mostrando-se sob a figura da esposa do morto 6 imaginar ver ou ouvir; fantasiar alguém ou algo, ac. ou inf.: πάντοτε Λευκίππην φαντάζομαι a.tác. imagino ver Leucipe em toda parte ♦ pas. 7 ser imaginado: ἡδοναὶ φαντασθεῖσαι plat. prazeres imaginados 8 com. ser denunciado 9 ser visto ou ouvido em imaginação: ὁππότ᾽ ἂν μυκαὶ σηκοῖς ἔνι φαντάζωνται a.r. quando imaginam-se ouvir mugidos nos templos. 〈φαίνω〉</p></section></article>\n<article id=\"entry-dgp-42294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 88 na letra φ · nº geral 42294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aparição de coisas extraordinárias ou que provocam ilusão; visão 2 exposição; ostentação; exibição: μετὰ φαντασίας pol. com ostentação, φαν­τασίας ἕνεκα d.s. por ostenção 3 faculdade de imaginar; fantasia; imaginação 4 imagem que se oferece ao espírito; idéia 5 espetáculo; vista partic. de coisas extraordinárias e próprias para atingir a imaginação 6 aparência exterior; visual. 〈φαντάζω〉</p></section></article>\n<article id=\"entry-dgp-42295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντασιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 89 na letra φ · nº geral 42295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φανταστικός.</p></section></article>\n<article id=\"entry-dgp-42296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντασιοπλήκτως</h1><div class=\"entry-meta\"><span>DGP · ordem 90 na letra φ · nº geral 42296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo a tocar a imaginação. 〈φαντασία, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-42297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντασιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 91 na letra φ · nº geral 42297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer aparecer imagem ou fantasma na mente de alguém, ac. ♦ méd. pas. 2 imaginar; imaginar que se vê; ver pela imaginação, ac. 〈φαντασία〉</p></section></article>\n<article id=\"entry-dgp-42298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φάντασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 92 na letra φ · nº geral 42298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aparição; visão; sonho 2 reflexo na água 3 Fil. aparência; imagem 4 espectro; fantasma 5 fenômeno (celeste) 6 prodígio. 〈φαντασία〉</p></section></article>\n<article id=\"entry-dgp-42299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φαντασμάτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 93 na letra φ · nº geral 42299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de φάντασμα.</p></section></article>\n<article id=\"entry-dgp-42300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φανταστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 94 na letra φ · nº geral 42300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne à imaginação 2 capaz de imaginar ♦ ἡ φανταστική 3 arte de imaginar, gen. ♦ τὸ φανταστικόν 4 faculdade de imaginar; imaginação 5 faculdade de imaginar coisas vãs, de criar ilusões. 〈φαντάζω〉</p></section></article>\n";
